/// Basic agent to support early iteration of ZPR.
/// Probably missing things.
#[derive(Clone, Debug, Default, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub struct Agent {
  pub agent_type: Option<AgentType>,
  pub attrs: Option<BTreeMap<String, String>>,
  /// unix time stamp
  pub auth_expires: Option<i64>,
  /// assigned ZPR address
  pub zpr_addr: Option<Vec<u8>>,
  pub tether_addr: Option<Vec<u8>>,
  /// unique in this ZPRnet
  pub ident: Option<String>,
  pub provides: Option<Vec<String>>,
}

impl Agent {
  pub fn new<F1, F2, F3, F4, F5, F6, F7>(agent_type: F1, attrs: F2, auth_expires: F3, zpr_addr: F4, tether_addr: F5, ident: F6, provides: F7) -> Agent where F1: Into<Option<AgentType>>, F2: Into<Option<BTreeMap<String, String>>>, F3: Into<Option<i64>>, F4: Into<Option<Vec<u8>>>, F5: Into<Option<Vec<u8>>>, F6: Into<Option<String>>, F7: Into<Option<Vec<String>>> {
    Agent {
      agent_type: agent_type.into(),
      attrs: attrs.into(),
      auth_expires: auth_expires.into(),
      zpr_addr: zpr_addr.into(),
      tether_addr: tether_addr.into(),
      ident: ident.into(),
      provides: provides.into(),
    }
  }
}

impl TSerializable for Agent {
  fn read_from_in_protocol(i_prot: &mut dyn TInputProtocol) -> thrift::Result<Agent> {
    i_prot.read_struct_begin()?;
    let mut f_1: Option<AgentType> = None;
    let mut f_2: Option<BTreeMap<String, String>> = Some(BTreeMap::new());
    let mut f_3: Option<i64> = Some(0);
    let mut f_4: Option<Vec<u8>> = Some(Vec::new());
    let mut f_5: Option<Vec<u8>> = Some(Vec::new());
    let mut f_6: Option<String> = Some("".to_owned());
    let mut f_7: Option<Vec<String>> = Some(Vec::new());
    loop {
      let field_ident = i_prot.read_field_begin()?;
      if field_ident.field_type == TType::Stop {
        break;
      }
      let field_id = field_id(&field_ident)?;
      match field_id {
        1 => {
          let val = AgentType::read_from_in_protocol(i_prot)?;
          f_1 = Some(val);
        },
        2 => {
          let map_ident = i_prot.read_map_begin()?;
          let mut val: BTreeMap<String, String> = BTreeMap::new();
          for _ in 0..map_ident.size {
            let map_key_1 = i_prot.read_string()?;
            let map_val_2 = i_prot.read_string()?;
            val.insert(map_key_1, map_val_2);
          }
          i_prot.read_map_end()?;
          f_2 = Some(val);
        },
        3 => {
          let val = i_prot.read_i64()?;
          f_3 = Some(val);
        },
        4 => {
          let val = i_prot.read_bytes()?;
          f_4 = Some(val);
        },
        5 => {
          let val = i_prot.read_bytes()?;
          f_5 = Some(val);
        },
        6 => {
          let val = i_prot.read_string()?;
          f_6 = Some(val);
        },
        7 => {
          let list_ident = i_prot.read_list_begin()?;
          let mut val: Vec<String> = Vec::with_capacity(list_ident.size as usize);
          for _ in 0..list_ident.size {
            let list_elem_3 = i_prot.read_string()?;
            val.push(list_elem_3);
          }
          i_prot.read_list_end()?;
          f_7 = Some(val);
        },
        _ => {
          i_prot.skip(field_ident.field_type)?;
        },
      };
      i_prot.read_field_end()?;
    }
    i_prot.read_struct_end()?;
    let ret = Agent {
      agent_type: f_1,
      attrs: f_2,
      auth_expires: f_3,
      zpr_addr: f_4,
      tether_addr: f_5,
      ident: f_6,
      provides: f_7,
    };
    Ok(ret)
  }
  fn write_to_out_protocol(&self, o_prot: &mut dyn TOutputProtocol) -> thrift::Result<()> {
    let struct_ident = TStructIdentifier::new("Agent");
    o_prot.write_struct_begin(&struct_ident)?;
    if let Some(ref fld_var) = self.agent_type {
      o_prot.write_field_begin(&TFieldIdentifier::new("agent_type", TType::I32, 1))?;
      fld_var.write_to_out_protocol(o_prot)?;
      o_prot.write_field_end()?
    }
    if let Some(ref fld_var) = self.attrs {
      o_prot.write_field_begin(&TFieldIdentifier::new("attrs", TType::Map, 2))?;
      o_prot.write_map_begin(&TMapIdentifier::new(TType::String, TType::String, fld_var.len() as i32))?;
      for (k, v) in fld_var {
        o_prot.write_string(k)?;
        o_prot.write_string(v)?;
      }
      o_prot.write_map_end()?;
      o_prot.write_field_end()?
    }
    if let Some(fld_var) = self.auth_expires {
      o_prot.write_field_begin(&TFieldIdentifier::new("auth_expires", TType::I64, 3))?;
      o_prot.write_i64(fld_var)?;
      o_prot.write_field_end()?
    }
    if let Some(ref fld_var) = self.zpr_addr {
      o_prot.write_field_begin(&TFieldIdentifier::new("zpr_addr", TType::String, 4))?;
      o_prot.write_bytes(fld_var)?;
      o_prot.write_field_end()?
    }
    if let Some(ref fld_var) = self.tether_addr {
      o_prot.write_field_begin(&TFieldIdentifier::new("tether_addr", TType::String, 5))?;
      o_prot.write_bytes(fld_var)?;
      o_prot.write_field_end()?
    }
    if let Some(ref fld_var) = self.ident {
      o_prot.write_field_begin(&TFieldIdentifier::new("ident", TType::String, 6))?;
      o_prot.write_string(fld_var)?;
      o_prot.write_field_end()?
    }
    if let Some(ref fld_var) = self.provides {
      o_prot.write_field_begin(&TFieldIdentifier::new("provides", TType::List, 7))?;
      o_prot.write_list_begin(&TListIdentifier::new(TType::String, fld_var.len() as i32))?;
      for e in fld_var {
        o_prot.write_string(e)?;
      }
      o_prot.write_list_end()?;
      o_prot.write_field_end()?
    }
    o_prot.write_field_stop()?;
    o_prot.write_struct_end()
  }
}

