    let res = match &*message_ident.name {
      "hello" => {
        self.process_hello(message_ident.sequence_number, i_prot, o_prot)
      },
      "authenticate" => {
        self.process_authenticate(message_ident.sequence_number, i_prot, o_prot)
      },
      "de_register" => {
        self.process_de_register(message_ident.sequence_number, i_prot, o_prot)
      },
      "authorize_connect" => {
        self.process_authorize_connect(message_ident.sequence_number, i_prot, o_prot)
      },
      "agent_disconnect" => {
        self.process_agent_disconnect(message_ident.sequence_number, i_prot, o_prot)
      },
      "ping" => {
        self.process_ping(message_ident.sequence_number, i_prot, o_prot)
      },
      "request_visa" => {
        self.process_request_visa(message_ident.sequence_number, i_prot, o_prot)
      },
      method => {
        Err(
          thrift::Error::Application(
            ApplicationError::new(
              ApplicationErrorKind::UnknownMethod,
              format!("unknown method {}", method)
            )
          )
        )
      },
    };
    thrift::server::handle_process_result(&message_ident, res, o_prot)
